import type { ActivityEvent, ActivityPage, BrowserActivityObservation } from "@infinite-quest/contracts";
export const scope = { apiBase: "https://local/api/v1", ownerUserId: "11111111-1111-4111-8111-111111111111", campaignId: "22222222-2222-4222-8222-222222222222" };
export const now = 1790985600000;
export const iso = new Date(now).toISOString();
export function event(n: number): ActivityEvent { return { version: 1, eventId: `10000000-0000-4000-8000-${String(n).padStart(12,"0")}`, sequence: String(n), occurredAt: iso, publishedAt: iso, campaignId: scope.campaignId, source: "generation", kind: "generation.queued", severity: "info", status: "queued", jobId: null, generationJobId: null, segmentId: null, turnId: null, turnNumber: null, attemptNumber: null, diagnostic: null }; }
export function observation(n: number): Omit<BrowserActivityObservation,"sequence"> { return { version: 1, observationId: `20000000-0000-4000-8000-${String(n).padStart(12,"0")}`, observedAt: iso, campaignId: scope.campaignId, kind: "browser.campaign_load", severity: "info", jobId: null, generationJobId: null, segmentId: null, turnId: null, diagnostic: null }; }
export function page(events: ActivityEvent[], hasMore = false, high?: string): ActivityPage { const seqs = events.map(e => BigInt(e.sequence)); const max = seqs.reduce((a,b) => a > b ? a : b, 0n).toString(); const min = seqs.reduce((a,b) => a < b ? a : b, seqs[0] ?? 0n).toString(); return { version: 1, events, nextAfter: `after:${max}`, nextBefore: events.length ? `before:${min}` : null, hasMore, coverage: { capturedSince: iso, retentionDays:30, oldestAvailableSequence: events.length ? min : null, latestPublishedSequence: high ?? max, pendingPublication:false, incomplete:false, resetRequired:false } }; }
